interface APIKey {
  id: string;
  name: string;
  key_hash: string;
  key_prefix: string;
  tier: string;
  status: string;
  rate_limit: number;
  requests_today: number;
  total_requests: number;
  last_used: string | null;
  created_at: string;
}

async function generateKey(): Promise<{ full: string; prefix: string; hash: string }> {
  // Use crypto.getRandomValues for cryptographically secure key generation
  const random = crypto.getRandomValues(new Uint8Array(32));
  const b64 = btoa(String.fromCharCode(...random))
    .replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
  const full   = `tl_live_${b64}`;
  const prefix = full.slice(0, 16);   // shown to user for identification only

  // Hash with SHA-256 — only hash stored in DB, never the raw key
  const hashBuf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(full));
  const hash    = [...new Uint8Array(hashBuf)].map(b => b.toString(16).padStart(2, "0")).join("");

  return { full, prefix, hash };
}

