const METHOD_CLR: Record<string, string> = {
  GET:    "bg-green-500/15 text-green-500 border-green-500/40",
  POST:   "bg-blue-500/15 text-blue-400 border-blue-500/40",
  DELETE: "bg-destructive/15 text-destructive border-destructive/40",
};
const TIER_CLR: Record<string, string> = {
  Free:       "bg-border/30 text-muted-foreground border-border/60",
  Pro:        "bg-primary/15 text-primary border-primary/40",
  Enterprise: "bg-yellow-500/15 text-yellow-500 border-yellow-500/40",
};

export default function APIPortal() {
  const { toast } = useToast();
  const [keys, setKeys]         = useState<APIKey[]>([]);
  const [loading, setLoading]   = useState(true);
  const [newKeyName, setNewKeyName] = useState("");
  const [revealedKey, setRevealedKey] = useState<string | null>(null);
  const [newKeyFull, setNewKeyFull]   = useState<{ id: string; full: string } | null>(null);
  const [copied, setCopied]     = useState<string | null>(null);
  const [expandedEp, setExpandedEp] = useState<string | null>(null);

  const loadKeys = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("api_keys")
      .select("*")
      .eq("status", "active")
      .order("created_at", { ascending: false });
    if (error) toast({ title: "Load failed", description: error.message, variant: "destructive" });
    else setKeys((data ?? []) as APIKey[]);
    setLoading(false);
  }, [toast]);

  useEffect(() => { loadKeys(); }, [loadKeys]);

  const copyText = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopied(id);
    setTimeout(() => setCopied(null), 2000);
  };

  const createKey = async () => {
    if (keys.length >= 1) {
      toast({ title: "Upgrade required", description: "Free tier allows 1 API key. Upgrade to Pro for more.", variant: "destructive" });
      return;
    }
    const name = newKeyName.trim() || `Key ${keys.length + 1}`;
    const { full, prefix, hash } = await generateKey();
    const { data, error } = await supabase
      .from("api_keys")
      .insert([{ name, key_hash: hash, key_prefix: prefix, tier: "free", status: "active", rate_limit: 100 }])
      .select()
      .single();
    if (error) { toast({ title: "Create failed", description: error.message, variant: "destructive" }); return; }
    const row = data as APIKey;
    setKeys(prev => [row, ...prev]);
    setNewKeyFull({ id: row.id, full });
    setNewKeyName("");
    toast({ title: "API key created", description: "Copy your key now — it won't be shown again." });
  };

  const revokeKey = async (id: string) => {
    const { error } = await supabase.from("api_keys").update({ status: "revoked" }).eq("id", id);
    if (error) { toast({ title: "Revoke failed", description: error.message, variant: "destructive" }); return; }
    setKeys(prev => prev.filter(k => k.id !== id));
    if (newKeyFull?.id === id) setNewKeyFull(null);
    toast({ title: "Key revoked" });
  };

  const totalCalls = keys.reduce((s, k) => s + (k.total_requests ?? 0), 0);

  // Live rate-limit window usage from api_rate_limits table
  const { data: rateLimitData } = useQuery({
    queryKey: ["api_rate_limits", keys.map(k => k.id)],
    queryFn: async () => {
      if (keys.length === 0) return [];
      const windowStart = new Date(Math.floor(Date.now() / 3_600_000) * 3_600_000).toISOString();
      const { data } = await supabase
        .from("api_rate_limits")
        .select("api_key_id, request_count, window_start")
        .in("api_key_id", keys.map(k => k.id))
        .eq("window_start", windowStart);
      return data ?? [];
    },
    enabled: keys.length > 0,
    staleTime: 60_000,
    refetchInterval: 60_000,
  });

  const currentHourUsage = (rateLimitData ?? []).reduce((s: number, r: any) => s + r.request_count, 0);

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      <div className="mb-8 flex items-start justify-between">
        <div className="flex items-center gap-3">
          <Key className="h-6 w-6 text-primary" />
          <div>
            <h1 className="text-3xl font-bold">API Portal</h1>
            <p className="text-muted-foreground text-sm">Integrate ThreatLens intelligence into your security stack and automation pipelines.</p>
          </div>
        </div>
        <Button variant="outline" size="sm" onClick={loadKeys} disabled={loading}>
          <RefreshCw className={`w-4 h-4 mr-2 ${loading ? "animate-spin" : ""}`} />Refresh
        </Button>
      </div>

      <Tabs defaultValue="keys">
        <TabsList className="mb-6">
          <TabsTrigger value="keys"  className="gap-2"><Key      className="w-4 h-4" />API Keys</TabsTrigger>
          <TabsTrigger value="usage" className="gap-2"><Activity className="w-4 h-4" />Usage</TabsTrigger>
          <TabsTrigger value="docs"  className="gap-2"><Book     className="w-4 h-4" />Reference</TabsTrigger>
        </TabsList>

        {/* API Keys */}
        <TabsContent value="keys">
          <div className="grid md:grid-cols-3 gap-6">
            <div className="md:col-span-2 space-y-4">
              <Card>
                <CardHeader className="pb-3"><CardTitle className="text-sm">Create New API Key</CardTitle></CardHeader>
                <CardContent>
                  <div className="flex gap-3">
                    <Input value={newKeyName} onChange={e => setNewKeyName(e.target.value)}
                      onKeyDown={e => e.key === "Enter" && createKey()}
                      placeholder="Key name (e.g. production-siem)" className="h-9" />
                    <Button onClick={createKey} className="h-9 gap-2"><Plus className="w-4 h-4" />Generate</Button>
                  </div>
                  <p className="text-xs text-muted-foreground mt-2">Free: 1 key · Pro: 5 keys · Enterprise: unlimited</p>
                </CardContent>
              </Card>

              {newKeyFull && (
                <Card className="border-green-500/30 bg-green-500/5">
                  <CardContent className="pt-4 pb-4 px-5">
                    <p className="text-xs font-semibold text-green-400 mb-2">New key generated — copy it now, it won't be shown again</p>
                    <div className="flex items-center gap-2">
                      <code className="text-xs font-mono flex-1 break-all">{newKeyFull.full}</code>
                      <Button size="sm" variant="ghost" className="h-7 shrink-0"
                        onClick={() => copyText(newKeyFull.full, "new")}>
                        {copied === "new" ? <Check className="w-3.5 h-3.5 text-green-500" /> : <Copy className="w-3.5 h-3.5" />}
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              )}

              {loading ? (
                <div className="text-center py-8 text-muted-foreground text-sm">Loading keys…</div>
              ) : keys.length === 0 ? (
                <div className="text-center py-12 border border-dashed rounded-xl text-muted-foreground">
                  <Key className="w-10 h-10 mx-auto mb-3 opacity-20" />
                  <p>No API keys yet. Generate one above.</p>
                </div>
              ) : keys.map(k => (
                <Card key={k.id}>
                  <CardContent className="py-4 px-5">
                    <div className="flex items-start gap-3">
                      <Key className="w-4 h-4 text-muted-foreground mt-0.5 shrink-0" />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-2">
                          <span className="font-medium text-sm">{k.name}</span>
                          <Badge variant="outline" className="text-[9px] border-green-500/40 text-green-500">Active</Badge>
                          <Badge variant="outline" className="text-[9px]">{k.tier}</Badge>
                        </div>
                        <div className="flex items-center gap-2">
                          <code className="text-xs font-mono text-muted-foreground">
                            {k.key_prefix}{"•".repeat(30)}
                          </code>
                        </div>
                        <div className="flex gap-4 mt-2 text-[10px] text-muted-foreground">
                          <span>Created: {new Date(k.created_at).toLocaleDateString()}</span>
                          <span>Calls: {k.total_requests.toLocaleString()}</span>
                          <span>Limit: {k.rate_limit}/min</span>
                        </div>
                      </div>
                      <Button size="sm" variant="ghost" className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive"
                        onClick={() => revokeKey(k.id)}>
                        <Trash2 className="w-3 h-3" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            <div className="space-y-3">
              <Card>
                <CardHeader className="pb-2 pt-3 px-4"><CardTitle className="text-xs">Authentication</CardTitle></CardHeader>
                <CardContent className="px-4 pb-3 space-y-2 text-xs text-muted-foreground">
                  <p>Include in request header:</p>
                  <code className="block p-2 rounded bg-muted text-[11px] font-mono">X-API-Key: tl_YOUR_KEY</code>
                  <p>Or as query param:</p>
                  <code className="block p-2 rounded bg-muted text-[11px] font-mono">?api_key=tl_YOUR_KEY</code>
                </CardContent>
              </Card>
              <Card>
                <CardHeader className="pb-2 pt-3 px-4"><CardTitle className="text-xs">Rate Limits</CardTitle></CardHeader>
                <CardContent className="px-4 pb-3 space-y-1.5 text-xs">
                  {[["Free","10 req/min, 100/month"],["Pro","60 req/min, 10k/month"],["Enterprise","Unlimited"]].map(([t,l]) => (
                    <div key={t} className="flex justify-between">
                      <span className="text-muted-foreground">{t}</span>
                      <span className="font-mono text-[10px]">{l}</span>
                    </div>
                  ))}
                </CardContent>
              </Card>
            </div>
          </div>
        </TabsContent>

        {/* Usage */}
        <TabsContent value="usage">
          <div className="grid md:grid-cols-3 gap-4 mb-6">
            {[
              { label: "Total API Calls", value: totalCalls.toLocaleString(), sub: "all time" },
              { label: "Active Keys", value: keys.length, sub: `of ${keys.length >= 1 ? "1 (free)" : "0"} used` },
              { label: "This Hour", value: currentHourUsage.toLocaleString(), sub: `/ ${keys[0]?.rate_limit ?? 100} limit` },
            ].map(m => (
              <Card key={m.label}>
                <CardContent className="pt-5 pb-4">
                  <div className="text-xs text-muted-foreground mb-1">{m.label}</div>
                  <div className="text-2xl font-bold">{m.value}</div>
                  <div className="text-xs text-muted-foreground">{m.sub}</div>
                </CardContent>
              </Card>
            ))}
          </div>
          <Card>
            <CardHeader><CardTitle className="text-sm">Usage Quota (Free Tier)</CardTitle></CardHeader>
            <CardContent>
              <div className="space-y-3">
                <div>
                  <div className="flex justify-between text-xs mb-1">
                    <span>Enrichments used</span>
                    <span>{totalCalls} / 100</span>
                  </div>
                  <Progress value={Math.min((totalCalls / 100) * 100, 100)} className="h-2" />
                </div>
                <p className="text-xs text-muted-foreground">Upgrade to Pro for 10,000 enrichments/month and detailed analytics.</p>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Docs */}
        <TabsContent value="docs">
          <div className="space-y-3">
            {ENDPOINTS.map(ep => (
              <Card key={ep.path}>
                <div className="flex items-center gap-3 px-5 py-3.5 cursor-pointer"
                  onClick={() => setExpandedEp(expandedEp === ep.path ? null : ep.path)}>
                  <Badge className={`border text-[10px] font-mono w-14 justify-center ${METHOD_CLR[ep.method]}`}>{ep.method}</Badge>
                  <code className="text-sm font-mono flex-1">{ep.path}</code>
                  <Badge className={`border text-[9px] ${TIER_CLR[ep.tier]}`}>{ep.tier}+</Badge>
                </div>
                {expandedEp === ep.path && (
                  <div className="border-t border-border/40 px-5 pb-5 pt-4 space-y-3">
                    <p className="text-sm text-muted-foreground">{ep.desc}</p>
                    <div className="grid md:grid-cols-2 gap-3">
                      <div>
                        <p className="text-xs font-medium mb-1.5">Request</p>
                        <pre className="bg-muted/40 border rounded-lg p-3 text-[11px] font-mono overflow-x-auto whitespace-pre-wrap">{ep.example}</pre>
                      </div>
                      <div>
                        <p className="text-xs font-medium mb-1.5">Response</p>
                        <pre className="bg-muted/40 border rounded-lg p-3 text-[11px] font-mono overflow-x-auto whitespace-pre-wrap">{ep.response}</pre>
                      </div>
                    </div>
                  </div>
                )}
              </Card>
            ))}
          </div>
        </TabsContent>

        {/* Plans tab removed per product decision */}
      </Tabs>
    </div>
  );
}
